def _runs(indices):
    if not indices:
        return []
    out = []
    start = prev = indices[0]
    for x in indices[1:]:
        if x != prev + 1:
            out.append((start, prev))
            start = x
        prev = x
    out.append((start, prev))
    return out


def _bands(grid, horizontal=True):
    n = len(grid) if horizontal else len(grid[0])
    m = len(grid[0]) if horizontal else len(grid)
    occupied = []
    for i in range(n):
        occupied.append(any(grid[i][j] != 0 for j in range(m)) if horizontal
                        else any(grid[j][i] != 0 for j in range(m)))
    return _runs([i for i, yes in enumerate(occupied) if yes])


def transform(grid):
    out = [row[:] for row in grid]
    rb = _bands(grid, True)
    cb = _bands(grid, False)
    if not rb or not cb:
        return out

    # Each object is a solid nonzero band separated from the next by a zero gutter.
    # The center of each band carries its marker/color.
    rh = Counter(b - a + 1 for a, b in rb).most_common(1)[0][0]
    cw = Counter(b - a + 1 for a, b in cb).most_common(1)[0][0]
    rcenters = [a + rh // 2 for a, _ in rb]
    ccenters = [a + cw // 2 for a, _ in cb]
    cells = [(ri, ci, grid[ri][ci]) for ri in rcenters for ci in ccenters
             if ri < len(grid) and ci < len(grid[0]) and grid[ri][ci] != 0]
    if not cells:
        return out
    neutral = Counter(color for _, _, color in cells).most_common(1)[0][0]

    # Join the first and last occurrences of each non-neutral marker, drawing
    # only through the empty gutters between neighboring objects.
    for ri in rcenters:
        vals = [grid[ri][ci] if ri < len(grid) and ci < len(grid[0]) else 0
                for ci in ccenters]
        for color in set(vals) - {0, neutral}:
            places = [j for j, value in enumerate(vals) if value == color]
            if len(places) < 2:
                continue
            for j in range(places[0], places[-1]):
                for c in range(cb[j][1] + 1, cb[j + 1][0]):
                    out[ri][c] = color

    for ci in ccenters:
        vals = [grid[ri][ci] if ri < len(grid) and ci < len(grid[0]) else 0
                for ri in rcenters]
        for color in set(vals) - {0, neutral}:
            places = [j for j, value in enumerate(vals) if value == color]
            if len(places) < 2:
                continue
            for j in range(places[0], places[-1]):
                for r in range(rb[j][1] + 1, rb[j + 1][0]):
                    out[r][ci] = color
    return out
'''
