source2 = '''from collections import Counter, deque


def _runs(indices):
    if not indices:
        return []
    out = []
    start = prev = indices[0]
    for x in indices[1:]:
        if x != prev + 1:
            out.append((start, prev))
            start = x
        prev = x
    out.append((start, prev))
    return out


def _bands(grid, horizontal=True):
    n = len(grid) if horizontal else len(grid[0])
    m = len(grid[0]) if horizontal else len(grid)
    occupied = []
    for i in range(n):
        occupied.append(any(grid[i][j] != 0 for j in range(m)) if horizontal
                        else any(grid[j][i] != 0 for j in range(m)))
    return _runs([i for i, yes in enumerate(occupied) if yes])


def _marker_bounds(grid, rb, cb, ri, ci, color):
    r0, r1 = rb
    c0, c1 = cb
    seen = {(ri, ci)}
    todo = deque([(ri, ci)])
    while todo:
        r, c = todo.popleft()
        for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
            if r0 <= nr <= r1 and c0 <= nc <= c1 and (nr,nc) not in seen and grid[nr][nc] == color:
                seen.add((nr,nc))
                todo.append((nr,nc))
    return (min(r for r,c in seen), max(r for r,c in seen),
            min(c for r,c in seen), max(c for r,c in seen))


def transform(grid):
    out = [row[:] for row in grid]
    rb = _bands(grid, True)
    cb = _bands(grid, False)
    if not rb or not cb:
        return out

    rh = Counter(b-a+1 for a,b in rb).most_common(1)[0][0]
    cw = Counter(b-a+1 for a,b in cb).most_common(1)[0][0]
    rcenters = [a + rh//2 for a,_ in rb]
    ccenters = [a + cw//2 for a,_ in cb]
    nr, nc = len(grid), len(grid[0])
    centers = [(i,j,grid[i][j]) for i in rcenters for j in ccenters
               if i < nr and j < nc and grid[i][j] != 0]
    if not centers:
        return out
    neutral = Counter(color for _,_,color in centers).most_common(1)[0][0]

    # A colored marker can be a single pixel or a compact patch inside each tile.
    bounds = {}
    for i,ri in enumerate(rcenters):
        for j,ci in enumerate(ccenters):
            if ri < nr and ci < nc and grid[ri][ci] != 0:
                color = grid[ri][ci]
                bounds[i,j] = _marker_bounds(grid, rb[i], cb[j], ri, ci, color)

    for i,ri in enumerate(rcenters):
        vals = [grid[ri][ci] if ri < nr and ci < nc else 0 for ci in ccenters]
        for color in set(vals) - {0,neutral}:
            places = [j for j,value in enumerate(vals) if value == color]
            if len(places) < 2:
                continue
            rlo,rhi,_,_ = bounds[i,places[0]]
            for j in range(places[0], places[-1]):
                for c in range(cb[j][1]+1, cb[j+1][0]):
                    for r in range(rlo,rhi+1):
                        out[r][c] = color

    for j,ci in enumerate(ccenters):
        vals = [grid[ri][ci] if ri < nr and ci < nc else 0 for ri in rcenters]
        for color in set(vals) - {0,neutral}:
            places = [i for i,value in enumerate(vals) if value == color]
            if len(places) < 2:
                continue
            _,_,clo,chi = bounds[places[0],j]
            for i in range(places[0], places[-1]):
                for r in range(rb[i][1]+1, rb[i+1][0]):
                    for c in range(clo,chi+1):
                        out[r][c] = color
    return out
'''
